#!/usr/bin/env python
# -*- coding: utf-8 -*-

"""  
Tests of loading / generating polars of a list of airfoils - Polar_Set.load_or_generate 
"""

import time

import pytest

from airfoileditor.model.airfoil            import Airfoil
from airfoileditor.model.airfoil_examples   import Example, Root_Example, Tip_Example
from airfoileditor.model.polar_set          import Polar_Set, Polar_Task, Polar_Definition
from airfoileditor.model.xo2_driver         import Worker


def _polar_def (re=300000, ncrit=7.0) -> Polar_Definition:
    """ a XFOIL polar definition - only those are generated by a Worker task"""
    polar_def = Polar_Definition ()
    polar_def.set_is_xfoil (True)
    polar_def.set_re (re)
    polar_def.set_ncrit (ncrit)
    return polar_def


def _airfoils (dir : str, polar_defs : list, n=2) -> list[Airfoil]:
    """ n saved airfoils having a xfoil polar set with polar_defs """

    examples = [Example, Root_Example, Tip_Example]
    airfoils = []

    for i in range (n):
        path = examples[i % len (examples)]().saveAs (dir=dir, destName=f"airfoil_{i}")
        airfoil = Airfoil (pathFileName=path)
        airfoil.load ()
        airfoil.set_polarSet (Polar_Set (airfoil, polar_def=polar_defs))
        airfoils.append (airfoil)

    return airfoils


@pytest.fixture(autouse=True)
def clean_tasks ():
    Polar_Task.instances.clear ()
    yield
    Polar_Task.instances.clear ()


@pytest.fixture
def no_worker_run (monkeypatch):
    """ tasks are created but the Worker isn't started """
    monkeypatch.setattr (Polar_Task, 'run', lambda self: None)


class Test_Load_Or_Generate:

    def test_task_per_airfoil (self, tmp_path, no_worker_run):

        airfoils = _airfoils (str(tmp_path), [_polar_def (re=300000), _polar_def (re=400000)])

        Polar_Set.load_or_generate (airfoils)

        tasks = Polar_Task.get_instances ()
        assert len (tasks) == 2                                     # never a task for polars of different airfoils
        assert all (task.n_polars == 2 for task in tasks)           # same ncrit - polars of an airfoil in one task 

        task_airfoils = [{polar.polar_set.airfoil for polar in task._polars} for task in tasks]
        assert all (len (a) == 1 for a in task_airfoils)
        assert {next(iter(a)) for a in task_airfoils} == set (airfoils)


    def test_different_ncrit_own_task (self, tmp_path, no_worker_run):

        airfoils = _airfoils (str(tmp_path), [_polar_def (ncrit=7.0), _polar_def (ncrit=9.0)], n=1)

        Polar_Set.load_or_generate (airfoils)

        assert len (Polar_Task.get_instances ()) == 2


    def test_polars_in_tasks_are_not_added_again (self, tmp_path, no_worker_run):

        airfoils = _airfoils (str(tmp_path), [_polar_def ()])

        Polar_Set.load_or_generate (airfoils)
        Polar_Set.load_or_generate (airfoils)

        assert len (Polar_Task.get_instances ()) == 2


    def test_airfoil_without_polar_set (self, tmp_path, no_worker_run):

        airfoils = _airfoils (str(tmp_path), [_polar_def ()])
        airfoils[0].set_polarSet (None)

        Polar_Set.load_or_generate (airfoils)

        assert len (Polar_Task.get_instances ()) == 1


    def test_vlm_polars_are_added_and_removed (self, tmp_path, no_worker_run):

        airfoils = _airfoils (str(tmp_path), [_polar_def ()], n=1)
        polar_set = airfoils[0].polarSet

        Polar_Set.load_or_generate (airfoils, VLM=True)

        assert len (polar_set.polars_VLM) == 1
        assert len (Polar_Task.get_instances ()) == 2               # forced transition polar has its own task

        Polar_Set.load_or_generate (airfoils, VLM=False)

        assert len (polar_set.polars_VLM) == 0
        assert len (polar_set.polars_normal) == 1


    def test_polar_set_method_for_one_airfoil (self, tmp_path, no_worker_run):

        airfoils = _airfoils (str(tmp_path), [_polar_def ()], n=1)

        airfoils[0].polarSet.load_or_generate_polars ()

        assert len (Polar_Task.get_instances ()) == 1


    @pytest.mark.slow                       # vscode: activate in settings.json
    def test_generate_polars_with_worker (self, tmp_path):

        Worker().isReady (".", min_version='1.0.3')
        if not Worker.ready:
            Worker.exe_dir = None
            Worker().isReady ("..", min_version='1.0.3')
        assert Worker.ready

        airfoils = _airfoils (str(tmp_path), [_polar_def (re=300000), _polar_def (re=400000)], n=3)

        Polar_Set.load_or_generate (airfoils)

        # do the job of the Watchdog until all tasks are done

        t0 = time.time()
        while Polar_Task.get_instances () and time.time() - t0 < 120:
            for task in Polar_Task.get_instances ():
                task.load_polars ()
                if task.isCompleted ():
                    task.finalize ()
            time.sleep (0.3)

        assert not Polar_Task.get_instances ()

        for airfoil in airfoils:
            for polar in airfoil.polarSet.polars:
                assert polar.isLoaded and not polar.error_occurred, polar.error_reason
                assert len (polar.cl) > 10

        assert not list (tmp_path.glob ("tmp~*"))                   # temporary input files are removed 
